def sum_of_a_beach(text):
    words = ["sand", "water", "fish", "sun"]
    count = 0
    lower_text = text.lower()

    for word in words:
        start = 0
        while True:
            idx = lower_text.find(word, start)
            if idx == -1:
                break
            count += 1
            start = idx + len(word)

    return count
